namespace Slice;

internal static class Program
{
    public static int Main(string[] args)
    {
        return SliceApp.Run(args, Console.Error, Console.OpenStandardOutput());
    }
}

public static class SliceApp
{
    public static int Run(string[] args, TextWriter stderr, Stream outputStream)
    {
        if (args.Length != 1)
        {
            stderr.WriteLine("Usage: slice <csv-file>");
            return 1;
        }

        try
        {
            CsvRoundTripper.CopyFileToStandardOutput(args[0], outputStream);
            return 0;
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or ArgumentException)
        {
            stderr.WriteLine(ex.Message);
            return 1;
        }
    }
}

public static class CsvRoundTripper
{
    public static void CopyFileToStandardOutput(string path, Stream output)
    {
        using var input = File.OpenRead(path);
        input.CopyTo(output);
        output.Flush();
    }
}

using System.Text;
using Slice;

var tests = new List<(string Name, Action Test)>
{
    ("copies csv bytes unchanged", CopiesCsvBytesUnchanged),
    ("returns failure when missing file argument", ReturnsFailureWhenMissingFileArgument),
};

var failures = 0;

foreach (var (name, test) in tests)
{
    try
    {
        test();
        Console.WriteLine($"PASS {name}");
    }
    catch (Exception ex)
    {
        failures++;
        Console.Error.WriteLine($"FAIL {name}: {ex.Message}");
    }
}

return failures == 0 ? 0 : 1;

static void CopiesCsvBytesUnchanged()
{
    var tempPath = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N") + ".csv");
    var originalBytes = Encoding.UTF8.GetBytes("name,age\r\nAda,36\r\nGrace,47\r\n");
    File.WriteAllBytes(tempPath, originalBytes);

    try
    {
        using var output = new MemoryStream();
        CsvRoundTripper.CopyFileToStandardOutput(tempPath, output);

        var copiedBytes = output.ToArray();
        if (!originalBytes.SequenceEqual(copiedBytes))
        {
            throw new Exception("output bytes differed from input bytes");
        }
    }
    finally
    {
        File.Delete(tempPath);
    }
}

static void ReturnsFailureWhenMissingFileArgument()
{
    using var output = new MemoryStream();
    using var stderr = new StringWriter();
    var exitCode = SliceApp.Run(Array.Empty<string>(), stderr, output);
    if (exitCode == 0)
    {
        throw new Exception("expected non-zero exit code");
    }
}

using System.Text;
using Slice;

var tests = new List<(string Name, Action Test)>
{
    ("selects named columns in requested order", SelectsNamedColumnsInRequestedOrder),
    ("returns failure when a selected column is missing", ReturnsFailureWhenSelectedColumnIsMissing),
    ("returns failure when arguments are invalid", ReturnsFailureWhenArgumentsAreInvalid),
};

var failures = 0;

foreach (var (name, test) in tests)
{
    try
    {
        test();
        Console.WriteLine($"PASS {name}");
    }
    catch (Exception ex)
    {
        failures++;
        Console.Error.WriteLine($"FAIL {name}: {ex.Message}");
    }
}

return failures == 0 ? 0 : 1;

static void SelectsNamedColumnsInRequestedOrder()
{
    var tempPath = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N") + ".csv");
    var originalBytes = Encoding.UTF8.GetBytes("name,age,city\r\nAda,36,London\r\nGrace,47,Paris\r\n");
    File.WriteAllBytes(tempPath, originalBytes);

    try
    {
        using var output = new MemoryStream();
        CsvRoundTripper.WriteSelectedColumns(tempPath, new[] { "name", "age" }, output);

        var result = Encoding.UTF8.GetString(output.ToArray());
        var expected = $"name,age{Environment.NewLine}Ada,36{Environment.NewLine}Grace,47{Environment.NewLine}";
        if (result != expected)
        {
            throw new Exception($"unexpected output: {result}");
        }
    }
    finally
    {
        File.Delete(tempPath);
    }
}

static void ReturnsFailureWhenSelectedColumnIsMissing()
{
    var tempPath = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N") + ".csv");
    File.WriteAllText(tempPath, "name,age\r\nAda,36\r\n");

    try
    {
        using var output = new MemoryStream();
        using var stderr = new StringWriter();
        var exitCode = SliceApp.Run([tempPath, "select", "name,city"], stderr, output);
        if (exitCode == 0)
        {
            throw new Exception("expected non-zero exit code");
        }

        if (!stderr.ToString().Contains("Column not found: city", StringComparison.Ordinal))
        {
            throw new Exception($"unexpected error output: {stderr}");
        }
    }
    finally
    {
        File.Delete(tempPath);
    }
}

static void ReturnsFailureWhenArgumentsAreInvalid()
{
    using var output = new MemoryStream();
    using var stderr = new StringWriter();
    var exitCode = SliceApp.Run(Array.Empty<string>(), stderr, output);
    if (exitCode == 0)
    {
        throw new Exception("expected non-zero exit code");
    }
}

namespace Slice;

internal static class Program
{
    public static int Main(string[] args)
    {
        return SliceApp.Run(args, Console.Error, Console.OpenStandardOutput());
    }
}

public static class SliceApp
{
    public static int Run(string[] args, TextWriter stderr, Stream outputStream)
    {
        if (args.Length != 3 || !string.Equals(args[1], "select", StringComparison.Ordinal))
        {
            stderr.WriteLine("Usage: slice <csv-file> select <column1,column2,...>");
            return 1;
        }

        try
        {
            var selectedColumns = args[2]
                .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            CsvRoundTripper.WriteSelectedColumns(args[0], selectedColumns, outputStream);
            return 0;
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or ArgumentException or InvalidOperationException)
        {
            stderr.WriteLine(ex.Message);
            return 1;
        }
    }
}

public static class CsvRoundTripper
{
    public static void WriteSelectedColumns(string path, IReadOnlyList<string> selectedColumns, Stream output)
    {
        using var reader = new StreamReader(File.OpenRead(path));
        using var writer = new StreamWriter(output, leaveOpen: true)
        {
            NewLine = Environment.NewLine
        };

        var headerLine = reader.ReadLine() ?? throw new InvalidOperationException("CSV file is empty");
        var headers = ParseCsvLine(headerLine);
        var headerIndexes = headers
            .Select((header, index) => new { header, index })
            .ToDictionary(x => x.header, x => x.index, StringComparer.Ordinal);

        var selectedIndexes = selectedColumns
            .Select(columnName => headerIndexes.TryGetValue(columnName, out var index)
                ? index
                : throw new InvalidOperationException($"Column not found: {columnName}"))
            .ToArray();

        writer.WriteLine(string.Join(",", selectedColumns));

        string? line;
        while ((line = reader.ReadLine()) is not null)
        {
            if (line.Length == 0)
            {
                writer.WriteLine();
                continue;
            }

            var values = ParseCsvLine(line);
            var projectedValues = selectedIndexes.Select(index => index < values.Count ? values[index] : string.Empty);
            writer.WriteLine(string.Join(",", projectedValues));
        }

        writer.Flush();
    }

    private static List<string> ParseCsvLine(string line)
    {
        var values = new List<string>();
        var current = new System.Text.StringBuilder();
        var inQuotes = false;

        for (var i = 0; i < line.Length; i++)
        {
            var ch = line[i];

            if (inQuotes)
            {
                if (ch == '"')
                {
                    if (i + 1 < line.Length && line[i + 1] == '"')
                    {
                        current.Append('"');
                        i++;
                    }
                    else
                    {
                        inQuotes = false;
                    }
                }
                else
                {
                    current.Append(ch);
                }
            }
            else if (ch == ',')
            {
                values.Add(current.ToString());
                current.Clear();
            }
            else if (ch == '"')
            {
                inQuotes = true;
            }
            else
            {
                current.Append(ch);
            }
        }

        values.Add(current.ToString());
        return values;
    }
}
